
"use client";

import { useEffect, useState } from "react";
import {
  Activity,
  ArrowUpRight,
  Globe2,
  LocateFixed,
  Radio,
  Satellite,
  Timer,
  Orbit,
} from "lucide-react";

type ISSPosition = {
  latitude: number;
  longitude: number;
  altitude: number;
  velocity: number;
  timestamp: number;
  visibility: string;
};

export default function Home() {
  const [iss, setIss] = useState<ISSPosition | null>(null);
  const [error, setError] = useState("");
  const [updated, setUpdated] = useState("");

  useEffect(() => {
    let active = true;

    async function fetchISS() {
      try {
        const response = await fetch(
          "https://api.wheretheiss.at/v1/satellites/25544",
          { cache: "no-store" }
        );

        if (!response.ok) throw new Error("Unable to fetch ISS data");

        const data: ISSPosition = await response.json();

        if (active) {
          setIss(data);
          setUpdated(new Date().toLocaleTimeString());
          setError("");
        }
      } catch {
        if (active) setError("Live telemetry is temporarily unavailable.");
      }
    }

    fetchISS();
    const interval = setInterval(fetchISS, 5000);

    return () => {
      active = false;
      clearInterval(interval);
    };
  }, []);

  const latitude = iss?.latitude;
  const longitude = iss?.longitude;

  const stats = [
    {
      label: "ALTITUDE",
      value: iss ? iss.altitude.toFixed(1) : "—",
      unit: "KM",
      icon: Orbit,
    },
    {
      label: "VELOCITY",
      value: iss ? Math.round(iss.velocity).toLocaleString() : "—",
      unit: "KM/H",
      icon: Activity,
    },
    {
      label: "LATITUDE",
      value: latitude !== undefined ? `${latitude.toFixed(3)}°` : "—",
      unit: "DEG",
      icon: LocateFixed,
    },
    {
      label: "LONGITUDE",
      value: longitude !== undefined ? `${longitude.toFixed(3)}°` : "—",
      unit: "DEG",
      icon: Globe2,
    },
  ];

  const mapUrl =
    iss && latitude !== undefined && longitude !== undefined
      ? `https://www.openstreetmap.org/?mlat=${latitude}&mlon=${longitude}#map=3/${latitude}/${longitude}`
      : "https://www.openstreetmap.org/";

  return (
    <main className="min-h-screen bg-[#070b14] text-slate-100">
      <header className="flex items-center justify-between border-b border-white/10 px-6 py-5 md:px-12">
        <a href="#" className="flex items-center gap-3">
          <div className="rounded-xl border border-cyan-300/30 bg-cyan-300/10 p-2">
            <Satellite className="text-cyan-300" size={23} />
          </div>
          <div>
            <p className="font-semibold tracking-[0.2em]">ORBITAL</p>
            <p className="text-[10px] tracking-[0.25em] text-slate-500">
              HUMANITY IN SPACE
            </p>
          </div>
        </a>

        <div className="flex items-center gap-2 rounded-full border border-white/10 px-3 py-2 text-xs">
          <span
            className={`h-2 w-2 rounded-full ${
              iss ? "animate-pulse bg-emerald-400" : "bg-amber-400"
            }`}
          />
          <span className="text-slate-300">
            {iss ? "TELEMETRY ACTIVE" : "CONNECTING"}
          </span>
        </div>
      </header>

      <section className="mx-auto max-w-7xl px-6 py-12 md:px-12 md:py-20">
        <div className="mb-10 grid gap-8 md:grid-cols-[1fr_auto] md:items-end">
          <div>
            <p className="mb-5 flex items-center gap-2 text-xs tracking-[0.3em] text-cyan-300">
              <Radio size={15} />
              LIVE ORBITAL TRACKING / ISS-25544
            </p>
            <h1 className="max-w-3xl text-5xl font-light leading-tight tracking-tight md:text-7xl">
              Somewhere above
              <br />
              <span className="font-semibold text-cyan-300">
                our world.
              </span>
            </h1>
            <p className="mt-5 max-w-xl leading-7 text-slate-400">
              Follow the International Space Station as it travels around
              Earth at nearly 28,000 kilometres per hour.
            </p>
          </div>

          <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-5 md:min-w-56">
            <p className="text-xs tracking-widest text-slate-500">
              CURRENT STATUS
            </p>
            <div className="mt-3 flex items-center gap-2">
              <span className="h-2 w-2 rounded-full bg-emerald-400" />
              <span className="text-lg">
                {iss ? "In orbit" : "Awaiting signal"}
              </span>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              {updated ? `Updated ${updated}` : "Establishing connection"}
            </p>
          </div>
        </div>

        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          {stats.map((stat) => {
            const Icon = stat.icon;
            return (
              <article
                key={stat.label}
                className="rounded-2xl border border-white/10 bg-white/[0.035] p-5 transition hover:border-cyan-300/30"
              >
                <div className="flex items-center justify-between">
                  <p className="text-xs tracking-[0.2em] text-slate-500">
                    {stat.label}
                  </p>
                  <Icon size={18} className="text-cyan-300" />
                </div>
                <div className="mt-6 flex items-baseline gap-2">
                  <span className="text-3xl font-light tabular-nums">
                    {stat.value}
                  </span>
                  <span className="text-xs tracking-widest text-slate-500">
                    {stat.unit}
                  </span>
                </div>
              </article>
            );
          })}
        </div>

        <section className="mt-6 overflow-hidden rounded-2xl border border-white/10 bg-[#0b1220]">
          <div className="flex flex-wrap items-center justify-between gap-4 border-b border-white/10 px-5 py-4 md:px-7">
            <div className="flex items-center gap-3">
              <Globe2 className="text-cyan-300" size={20} />
              <div>
                <h2 className="font-medium">Station position</h2>
                <p className="text-xs text-slate-500">
                  Current ground coordinates
                </p>
              </div>
            </div>
            <a
              href={mapUrl}
              target="_blank"
              rel="noreferrer"
              className="flex items-center gap-2 rounded-lg border border-white/10 px-3 py-2 text-xs text-cyan-300 transition hover:bg-white/5"
            >
              Open interactive map <ArrowUpRight size={14} />
            </a>
          </div>

          <div className="relative min-h-72 overflow-hidden bg-[#081321] p-6 md:min-h-96 md:p-10">
            <div
              className="pointer-events-none absolute inset-0 opacity-20"
              style={{
                backgroundImage:
                  "linear-gradient(rgba(103,232,249,.16) 1px, transparent 1px), linear-gradient(90deg, rgba(103,232,249,.16) 1px, transparent 1px)",
                backgroundSize: "42px 42px",
              }}
            />

            <div className="relative z-10 grid min-h-56 place-items-center md:min-h-72">
              <div className="w-full max-w-xl">
                <div className="mb-5 flex items-center justify-between text-xs tracking-widest text-slate-500">
                  <span>LIVE POSITION FEED</span>
                  <span>{iss ? "SIGNAL RECEIVED" : "SEARCHING..."}</span>
                </div>

                <div className="relative overflow-hidden rounded-xl border border-cyan-300/20 bg-[#0b1b2b]/90 p-5 md:p-8">
                  <div className="absolute right-0 top-0 h-24 w-24 rounded-full bg-cyan-300/10 blur-3xl" />
                  <div className="relative flex items-center gap-4">
                    <div className="rounded-xl bg-cyan-300/10 p-3">
                      <Satellite size={30} className="text-cyan-300" />
                    </div>
                    <div>
                      <p className="text-lg font-medium">ISS / ZARYA</p>
                      <p className="mt-1 text-xs text-slate-500">
                        NORAD ID 25544
                      </p>
                    </div>
                  </div>

                  <div className="my-6 h-px bg-white/10" />

                  <div className="grid grid-cols-2 gap-6">
                    <div>
                      <p className="text-xs text-slate-500">LATITUDE</p>
                      <p className="mt-2 text-xl tabular-nums text-cyan-200">
                        {latitude !== undefined
                          ? `${latitude.toFixed(4)}°`
                          : "Waiting..."}
                      </p>
                    </div>
                    <div>
                      <p className="text-xs text-slate-500">LONGITUDE</p>
                      <p className="mt-2 text-xl tabular-nums text-cyan-200">
                        {longitude !== undefined
                          ? `${longitude.toFixed(4)}°`
                          : "Waiting..."}
                      </p>
                    </div>
                  </div>

                  {error && (
                    <p className="mt-5 text-sm text-amber-300">{error}</p>
                  )}
                </div>

                <p className="mt-4 text-center text-xs leading-5 text-slate-500">
                  This panel shows live telemetry. The map link opens the
                  station&apos;s current approximate ground position.
                </p>
              </div>
            </div>
          </div>
        </section>

        <footer className="mt-8 flex flex-col justify-between gap-3 border-t border-white/10 pt-5 text-xs text-slate-500 sm:flex-row">
          <p>ORBITAL © 2026 · Built for Earth watchers.</p>
          <p className="flex items-center gap-2">
            <Timer size={14} /> Refreshes every 5 seconds
          </p>
        </footer>
      </section>
    </main>
  );
}
